SELECT

FROM order_info order_info


		AND order_info.id = #{query.id}


		AND order_info.shop_id = #{query.shopId}


		AND order_info.user_id = #{query.userId}



			AND order_info.is_pay = '0'
			AND order_info.status is null


			AND order_info.status = #{query.status}::text



		AND order_info.is_pay = #{query.isPay}


		AND order_info.payment_type = #{query.paymentType}


		AND order_info.delivery_way = ANY(string_to_array(#{query.deliveryWay}, ','))


		AND order_info.order_no = #{query.orderNo}


		AND order_info.create_time >= #{query.beginTime}


		AND #{query.endTime} >= order_info.create_time


		AND order_info.app_type = #{query.appType}


		AND order_info.order_type = #{query.orderType}


		AND order_info.name LIKE CONCAT('%',#{query.name},'%')


		AND order_info.app_id = #{query.appId}



		AND EXISTS (
			SELECT 1 FROM zhiflow_wx.wx_app wx_app
			WHERE wx_app.id = order_info.app_id
			AND wx_app.del_flag = '0'
			AND wx_app.name LIKE CONCAT('%',#{query.appName},'%')
		)

SELECT
	SUM(order_info.payment_price)
FROM order_info order_info


		AND order_info.shop_id = #{query.shopId}


		AND order_info.user_id = #{query.userId}


		AND order_info.status IN

			#{status}





			AND order_info.is_pay = '0'
			AND order_info.status is null


			AND order_info.status = #{query.status}::text



		AND order_info.is_pay = #{query.isPay}


		AND order_info.delivery_way = #{query.deliveryWay}


		AND order_info.order_no = #{query.orderNo}


		AND order_info.create_time >= #{query.beginTime}


		AND #{query.endTime} >= order_info.create_time

SELECT

FROM order_info order_info
WHERE order_info.id = #{id}

SELECT spu_name as spu_name, COUNT(*) ct FROM order_item order_item LEFT JOIN order_info order_info ON order_item.order_id = order_info.id WHERE order_info.is_pay = '1'
AND order_info.shop_id = #{query.shopId}
AND order_info.create_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.create_time
GROUP BY spu_id, spu_name ORDER BY ct DESC LIMIT 10;

SELECT shop_info.name, COUNT(*) ct FROM order_item order_item LEFT JOIN shop_info shop_info ON order_item.shop_id = shop_info.id LEFT JOIN order_info order_info ON order_item.order_id = order_info.id WHERE order_info.is_pay = '1'
AND order_info.shop_id = #{query.shopId}
AND order_info.create_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.create_time
GROUP BY order_item.shop_id, shop_info.name ORDER BY ct DESC;

SELECT goods_category.name, COUNT(*) ct FROM order_item order_item LEFT JOIN goods_spu goods_spu ON order_item.spu_id = goods_spu.id LEFT JOIN goods_category goods_category ON goods_spu.category_second = goods_category.id LEFT JOIN order_info order_info ON order_item.order_id = order_info.id WHERE order_info.is_pay = '1'
AND order_info.shop_id = #{query.shopId}
AND order_info.create_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.create_time
GROUP BY goods_spu.category_second, goods_category.name ORDER BY ct DESC;

SELECT spu_name as spu_name, SUM(order_item.payment_price) ct FROM order_item order_item LEFT JOIN order_info order_info ON order_item.order_id = order_info.id WHERE order_info.is_pay = '1'
AND order_info.shop_id = #{query.shopId}
AND order_info.create_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.create_time
GROUP BY spu_id, spu_name ORDER BY ct DESC LIMIT 10;

SELECT shop_info.name, SUM(order_item.payment_price) ct FROM order_item order_item LEFT JOIN shop_info shop_info ON order_item.shop_id = shop_info.id LEFT JOIN order_info order_info ON order_item.order_id = order_info.id WHERE order_info.is_pay = '1'
AND order_info.shop_id = #{query.shopId}
AND order_info.create_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.create_time
GROUP BY order_item.shop_id, shop_info.name ORDER BY ct DESC;

SELECT goods_category.name, SUM(order_item.payment_price) ct FROM order_item order_item LEFT JOIN goods_spu goods_spu ON order_item.spu_id = goods_spu.id LEFT JOIN goods_category goods_category ON goods_spu.category_second = goods_category.id LEFT JOIN order_info order_info ON order_item.order_id = order_info.id WHERE order_info.is_pay = '1'
AND order_info.shop_id = #{query.shopId}
AND order_info.create_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.create_time
GROUP BY goods_spu.category_second, goods_category.name ORDER BY ct DESC;

SELECT goods_spu.name, goods_spu.pic_urls AS picUrls, SUM(order_item.quantity) ct FROM order_item order_item LEFT JOIN goods_spu goods_spu ON order_item.spu_id = goods_spu.id LEFT JOIN order_info order_info ON order_item.order_id = order_info.id WHERE order_info.is_pay = '1'
AND order_info.shop_id = #{query.shopId}
AND order_info.create_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.create_time
GROUP BY goods_spu.id ORDER BY ct DESC LIMIT 10;

SELECT shop_info.name, shop_info.img_url AS imgUrl, SUM(order_item.quantity) ct FROM order_item order_item LEFT JOIN shop_info shop_info ON order_item.shop_id = shop_info.id LEFT JOIN order_info order_info ON order_item.order_id = order_info.id WHERE order_info.is_pay = '1'
AND order_info.shop_id = #{query.shopId}
AND order_info.create_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.create_time
GROUP BY order_item.shop_id, shop_info.name, shop_info.img_url ORDER BY ct DESC;

SELECT goods_category.name, SUM(order_item.quantity) ct FROM order_item order_item LEFT JOIN goods_spu goods_spu ON order_item.spu_id = goods_spu.id LEFT JOIN goods_category goods_category ON goods_spu.category_second = goods_category.id LEFT JOIN order_info order_info ON order_item.order_id = order_info.id WHERE order_info.is_pay = '1'
AND order_info.shop_id = #{query.shopId}
AND order_info.create_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.create_time
GROUP BY goods_spu.category_second, goods_category.name ORDER BY ct DESC;

SELECT COALESCE(status::text, '0') as status, COUNT(*) as count FROM order_info WHERE del_flag = '0'
AND shop_id = #{shopId}
GROUP BY status UNION ALL SELECT '0' as status, COUNT(*) as count FROM order_info WHERE del_flag = '0' AND status IS NULL AND is_pay = '0'
AND shop_id = #{shopId}

SELECT to_char(order_info.payment_time, 'MM') || '月' as name, COALESCE(SUM(order_info.payment_price), 0) as value FROM order_info WHERE order_info.is_pay = '1' AND order_info.status IN ('1','2','3')
AND order_info.shop_id = #{query.shopId}
AND order_info.payment_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.payment_time
GROUP BY to_char(order_info.payment_time, 'MM') ORDER BY name

SELECT CASE WHEN sub.province IS NULL OR sub.province = '' THEN '未归属' WHEN sub.province LIKE '%省' THEN REPLACE(sub.province, '省', '') WHEN sub.province LIKE '%市' THEN REPLACE(sub.province, '市', '') WHEN sub.province = '内蒙古自治区' THEN '内蒙古' WHEN sub.province = '广西壮族自治区' THEN '广西' WHEN sub.province = '西藏自治区' THEN '西藏' WHEN sub.province = '宁夏回族自治区' THEN '宁夏' WHEN sub.province = '新疆维吾尔自治区' THEN '新疆' WHEN sub.province LIKE '%特别行政区' THEN REPLACE(sub.province, '特别行政区', '') ELSE sub.province END as name, COALESCE(SUM(sub.payment_price), 0) as value FROM ( SELECT split_part(area.mergename, ',', 2) as province, order_info.payment_price FROM order_info LEFT JOIN zhiflow_upms.table_area area ON order_info.area_id = area.id AND area.mergename LIKE '中国,%' WHERE order_info.del_flag = '0' AND order_info.is_pay = '1' AND order_info.status IN ('1','2','3')
AND order_info.shop_id = #{query.shopId}
AND order_info.payment_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.payment_time
) sub GROUP BY 1 ORDER BY value DESC

SELECT to_char(order_info.payment_time, 'YYYY-MM-DD') as name, COALESCE(SUM(order_info.payment_price), 0) as value FROM order_info WHERE order_info.del_flag = '0' AND order_info.is_pay = '1' AND order_info.status IN ('1','2','3')
AND order_info.shop_id = #{query.shopId}
AND order_info.payment_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.payment_time
GROUP BY to_char(order_info.payment_time, 'YYYY-MM-DD') ORDER BY name

SELECT CASE order_info.app_type WHEN 'MA' THEN '微信小程序' WHEN 'H5' THEN 'H5商城' WHEN 'H5-WX' THEN '微信公众号' WHEN 'H5-PC' THEN 'PC商城' WHEN 'UI' THEN 'APP' ELSE order_info.app_type END as name, COALESCE(SUM(order_info.payment_price), 0) as value FROM order_info WHERE order_info.del_flag = '0' AND order_info.is_pay = '1' AND order_info.status IN ('1','2','3')
AND order_info.shop_id = #{query.shopId}
AND order_info.payment_time >= #{query.beginTime}
AND #{query.endTime} >= order_info.payment_time
GROUP BY CASE order_info.app_type WHEN 'MA' THEN '微信小程序' WHEN 'H5' THEN 'H5商城' WHEN 'H5-WX' THEN '微信公众号' WHEN 'H5-PC' THEN 'PC商城' WHEN 'UI' THEN 'APP' ELSE order_info.app_type END ORDER BY value DESC LIMIT 5
